<?php
session_start();
header('X-Content-Type-Options: nosniff');
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
$config=__DIR__.'/config.php';
if(!is_file($config)){http_response_code(503);exit('Chybí config.php. Přejmenujte config.example.php na config.php a nastavte vlastní hash hesla podle návodu.');}
require $config;
if(!isset($adminPasswordHash)||!is_string($adminPasswordHash)){exit('Chybné nastavení hesla.');}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));
$error='';$notice='';
if(isset($_GET['logout'])){$_SESSION=[];session_destroy();header('Location: admin.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??'')){http_response_code(403);exit('Neplatný bezpečnostní token.');}
 if(isset($_POST['login'])){
  if(password_verify($_POST['password']??'',$adminPasswordHash)){session_regenerate_id(true);$_SESSION['logged']=true;header('Location: admin.php');exit;}else{$error='Nesprávné heslo.';}
 }elseif(!empty($_SESSION['logged'])){
  $path=__DIR__.'/menu.json';$items=json_decode(@file_get_contents($path),true);if(!is_array($items))$items=[];
  $action=$_POST['action']??'';
  if($action==='save'){
   $title=trim($_POST['title']??'');$slug=trim($_POST['slug']??'');$desc=trim($_POST['description']??'');$icon=trim($_POST['icon']??'');$category=trim($_POST['category']??'');$idx=filter_var($_POST['idx']??'-1',FILTER_VALIDATE_INT);
   if(!$title||!preg_match('/^[a-z0-9][a-z0-9_-]*$/',$slug))$error='Vyplňte název a platný adresář (malá písmena, číslice, - nebo _).';
   elseif(strlen($title)>160||strlen($desc)>500||strlen($icon)>24||strlen($category)>160)$error='Některé pole je příliš dlouhé.';
   else{$item=['title'=>$title,'slug'=>$slug,'description'=>$desc,'icon'=>$icon?:'⌘','category'=>$category];if($idx!==false&&$idx>=0&&isset($items[$idx]))$items[$idx]=$item;else $items[]=$item;$notice='Položka uložena.';}
  }elseif($action==='delete'){$idx=filter_var($_POST['idx']??'',FILTER_VALIDATE_INT);if($idx!==false&&isset($items[$idx])){array_splice($items,$idx,1);$notice='Položka odstraněna.';}}
  elseif($action==='move'){$idx=filter_var($_POST['idx']??'',FILTER_VALIDATE_INT);$step=(($_POST['direction']??'')==='up')?-1:1;$to=$idx===false?-1:$idx+$step;while(isset($items[$to])&&trim($items[$to]['category']??'')!==trim($items[$idx]['category']??''))$to+=$step;if($idx!==false&&isset($items[$idx],$items[$to])){[$items[$idx],$items[$to]]=[$items[$to],$items[$idx]];$notice='Pořadí změněno.';}}
  if(!$error){$json=json_encode($items,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$tmp=tempnam(__DIR__,'menu_');if($tmp===false||file_put_contents($tmp,$json,LOCK_EX)===false||!rename($tmp,$path)){$error='Soubor menu.json se nepodařilo uložit. Zkontrolujte práva zápisu.';if($tmp&&is_file($tmp))unlink($tmp);}else{header('Location: admin.php?ok='.urlencode($notice));exit;}}
 }
}
$items=json_decode(@file_get_contents(__DIR__.'/menu.json'),true);if(!is_array($items))$items=[];
$groups=[];$categories=['Matematika','Informatika'];foreach($items as $i=>$item){$category=trim($item['category']??'');$groups[$category][$i]=$item;if($category!==''&&!in_array($category,$categories,true))$categories[]=$category;}
$edit=filter_var($_GET['edit']??'',FILTER_VALIDATE_INT);$current=($edit!==false&&isset($items[$edit]))?$items[$edit]:null;
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administrace | Učíme se IT</title><link rel="stylesheet" href="style.css"></head><body><header><div class="wrap top"><a class="logo" href="/">&lt;/&gt; Učíme se IT</a><a class="adminlink" href="/">Zpět na web</a></div></header><main class="panel"><h1>Administrace</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="notice"><?=e($_GET['ok'])?></div><?php endif;?><?php if(empty($_SESSION['logged'])):?><div class="box"><h2>Přihlášení</h2><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="login" value="1"><label>Heslo správce</label><input type="password" name="password" required autocomplete="current-password"><p><button>Přihlásit se</button></p></form></div><?php else:?><p><a class="adminlink" href="?logout=1">Odhlásit se</a></p><div class="box"><h2><?= $current?'Upravit položku':'Přidat novou aplikaci'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save"><input type="hidden" name="idx" value="<?=$current?$edit:-1?>"><div class="fields"><div><label>Název</label><input name="title" required maxlength="160" value="<?=e($current['title']??'')?>" placeholder="Např. Databáze"></div><div><label>Název adresáře (bez lomítek)</label><input name="slug" required pattern="[a-z0-9][a-z0-9_-]*" value="<?=e($current['slug']??'')?>" placeholder="napr-databaze" id="slug-input"></div><div><label>Popis</label><input name="description" maxlength="500" value="<?=e($current['description']??'')?>" placeholder="Krátký popis aplikace"></div><div><label for="category-input">Skupina</label><input id="category-input" name="category" list="category-options" maxlength="160" value="<?=e($current['category']??'')?>" placeholder="Např. Matematika"><datalist id="category-options"><?php foreach($categories as $category):?><option value="<?=e($category)?>"></option><?php endforeach;?></datalist><small class="muted">Vyberte existující skupinu nebo napište novou. Prázdné pole znamená Nezařazené.</small></div><div><label>Symbol / emoji</label><input name="icon" maxlength="12" value="<?=e($current['icon']??'⌘')?>"></div></div><p><button>Uložit položku</button> <?php if($current):?><a class="adminlink" href="admin.php">Zrušit úpravy</a><?php endif;?></p></form><p class="muted">Výsledný odkaz: <strong id="url-preview">https://ucimeseit.cz/ucebnice/<?=e($current['slug']??'nazev-adresare')?>/</strong></p><p class="muted">Zadávejte pouze název adresáře bez lomítek. Adresář a jeho index.html nahrajte zvlášť přes FTP.</p></div><div class="box"><h2>Položky nabídky</h2><?php foreach($groups as $category=>$groupItems):?><section class="admin-group"><h3><?=e($category!==''?$category:'Nezařazené')?> (<?=count($groupItems)?>)</h3><?php foreach($groupItems as $i=>$item):?><div class="entry"><div><strong><?=e($item['title'])?></strong><small>/ucebnice/<?=e($item['slug'])?>/</small></div><div class="actions"><a class="adminlink" href="?edit=<?=$i?>">Upravit</a><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="move"><input type="hidden" name="idx" value="<?=$i?>"><button name="direction" value="up" aria-label="Posunout nahoru">↑</button><button name="direction" value="down" aria-label="Posunout dolů">↓</button></form><form method="post" onsubmit="return confirm('Opravdu odstranit položku z nabídky?')"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="idx" value="<?=$i?>"><button class="danger">Smazat</button></form></div></div><?php endforeach;?></section><?php endforeach;?></div><?php endif;?></main><script>const slugInput=document.getElementById("slug-input");const preview=document.getElementById("url-preview");if(slugInput&&preview){slugInput.addEventListener("input",()=>{preview.textContent="https://ucimeseit.cz/ucebnice/"+(slugInput.value.trim()||"nazev-adresare")+"/";});}</script></body></html>
